using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OnDiceCastedAuraEffect", menuName = "Data/Battle/Effects/Moonie/OnDiceCastedAura Effect")]
public class OnDiceCastedAuraEffect : Effect
{
	[Header("Action Specifics")]
	[SerializeField]
	private BattleAction battleAction;

	[SerializeField]
	[HideIf("enableSpecificDice")]
	private DiceTier diceTier;

	[SerializeField]
	private OmenLogic omenLogic;

	[SerializeField]
	private bool corruptedMoonlight;

	[SerializeField]
	private bool targetOwnerReceive;

	[SerializeField]
	[ShowIf("corruptedMoonlight")]
	private int woundHexAmount;

	[SerializeField]
	[ShowIf("corruptedMoonlight")]
	private HexAction woundHexAction;

	[SerializeField]
	private bool enableSpecificDice;

	[SerializeField]
	[ShowIf("enableSpecificDice")]
	private string specificDiceName;

	[SerializeField]
	[ShowIf("enableSpecificDice")]
	private Tag specificDiceTag;

	[SerializeField]
	private bool canTriggerCritical;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string arg = (enableSpecificDice ? specificDiceTag.GetTagName() : diceTier.GetLocalizedDiceTierWithDie());
		string text = Smart.Format(base.localizationManager.GetLocalizedWheneverYouPlayA(), arg) + base.localizationManager.GetLocalizedSpace();
		if (corruptedMoonlight)
		{
			string localizedAtTheStartOfTheBattle = base.localizationManager.GetLocalizedAtTheStartOfTheBattle(withSpace: true);
			string text2 = woundHexAction.GetActionDescription(woundHexAmount).LowercaseFirst();
			if (amount == EffectsValues.NO_VALUE)
			{
				amount = -1;
			}
			return localizedAtTheStartOfTheBattle + text2 + "\n" + text + battleAction.GetActionDescription(amount);
		}
		if (targetOwnerReceive)
		{
			string amount2 = amount.ToString();
			if (amount == EffectsValues.NO_VALUE)
			{
				amount2 = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedX();
			}
			return text + base.localizationManager.GetLocalizedEffectOwnerReceiveFormatted(purify: true, amount2);
		}
		return text + battleAction.GetActionDescription(amount) + AppendedDescription();
	}

	protected override string AppendedDescription()
	{
		if (!canTriggerCritical)
		{
			return "";
		}
		return "\n" + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedThisPurifyCanTriggerCritical();
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (corruptedMoonlight)
		{
			woundHexAction.CastAmount(woundHexAmount, effectOwner);
		}
	}

	public override int ActivateEffectWithSpecificDice(int effectAmount, GameObject effectOwner, Dice dice)
	{
		if (enableSpecificDice)
		{
			if (dice.DiceName != specificDiceName)
			{
				return effectAmount;
			}
		}
		else if (diceTier != dice.DiceTier)
		{
			return effectAmount;
		}
		ActivateEffect(effectAmount, effectOwner);
		return effectAmount;
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		PlayEffectActivationSFX();
		int actionValue = effectAmount;
		if (canTriggerCritical)
		{
			effectOwner.GetComponent<PlayerSpriteControl>().PlayAnimationForced(AnimationType.Attack, AnimationChangeType.ReturnToIdleAnimation);
			actionValue = effectOwner.GetComponent<PlayerEffects>().IsPlayerCriticalCheckCritical(effectAmount, fierceSquall: false, sentPur: false);
		}
		omenLogic.ActivateOmen(battleAction, actionValue, effectOwner, null);
		effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
		SpawnSecondVFX(GetVFXOwnerPosition(effectOwner), 4f);
		return effectAmount;
	}
}
